package main

import (
    "crypto/pbkdf2"
    "crypto/sha256"
    "encoding/base64"
)

func hashPassword(password string) (string, string, error) {
    salt := make([]byte, sha256.New().Size())
    if _, err := rand.Read(salt); err != nil {
        return "", "", err
    }

    key := pbkdf2.Key([]byte(password), salt, 10000, sha256.New().Size(), func(key []byte) hmac.Hash { return hmac.New(sha256.New, key) })

    saltStr := base64.StdEncoding.EncodeToString(salt)
    hashStr := base64.StdEncoding.EncodeToString(key)

    return saltStr, hashStr, nil
}
